    width: 400px;      /* any width */
    margin: 0 auto;
}

/* 3️⃣ Full‑page flex centering (both axes) */
.full-flex-center {
    display: flex;
    justify-content: center;
    align-items: center;
    height: 100vh;   /* optional: fill viewport */
}

/* 4️⃣ Full‑page grid centering (both axes) */
.full-grid-center {
    display: grid;
    place-items: center;
    height: 100vh;
}

/* 5️⃣ Center text inside a flex item */
.flex-item {
    flex: 1;
    text-align: center;   /* centers the text inside this item */
}
```

